"""Generate the isolated ICAO switch for standard FLAPS HANDLE INDEX.
Sources/coverage belong to support/display-values/flaps.json. SDK lever dictionaries
are separate and must never be substituted for the standard SimConnect index.
"""
from pathlib import Path
import json,argparse
ROOT=Path(__file__).resolve().parents[1]
def pas(s):return '+'.join("'"+s[i:i+120].replace("'","''")+"'" for i in range(0,len(s),120)) or "''"
def dictionary(labels):return r'\r\n'.join(str(i)+'='+v for i,v in enumerate(labels))
def generate(data):
 codes=sorted(data['aircraft']);enum=['faUnknown']+['fa'+c for c in codes]
 lines=['Unit FlapsHandleU;','','// Generated by tools/generate_flap_profiles.py; see support/display-values/flaps.json.','Interface','',' Uses System.Classes;','',' Function FlapsHandleDisplayValue(Const AircraftICAO : String; Const AircraftTitle : String = \x27\x27; HandlePositionCount : Integer = 0) : String;',' Function RecordedFlapPositionCount(Labels : TStrings; Const Values : TArray<Double>) : Integer;','','Implementation','',' Uses System.SysUtils, System.StrUtils, System.Math;','',' Type TFlapAircraft = (']
 for i in range(0,len(enum),8):lines.append('  '+', '.join(enum[i:i+8])+(',' if i+8<len(enum) else ');'))
 lines+=['',' Function FlapsHandleDisplayValue(Const AircraftICAO, AircraftTitle : String; HandlePositionCount : Integer) : String;','  Var','   DisplayValue, Title : String;','   ExpectedPositions : Integer;','  Begin',"   DisplayValue := '';",'   ExpectedPositions := 0;','   Title := UpperCase(AircraftTitle);','   Case TFlapAircraft(IndexText(UpperCase(Trim(AircraftICAO)), [']
 for i in range(0,len(codes),10):lines.append('    '+', '.join(pas(c) for c in codes[i:i+10])+(',' if i+10<len(codes) else ']) + 1) Of'))
 for code in codes:
  row=data['aircraft'][code]
  lines+=['    fa'+code+' :']
  if row.get('labels'):
   lines+=['     Begin','      DisplayValue := '+pas(dictionary(row['labels']))+';','      ExpectedPositions := '+str(len(row['labels']))+';','     End;']
  elif row.get('variants'):
   lines+=['     Begin']
   for i,v in enumerate(row['variants']):
    cond=' Or '.join("(Pos("+pas(t)+", Title) > 0)" for t in v['title_contains'])
    lines+=['      '+('If ' if i==0 else 'Else If ')+cond+' Then','       Begin','        DisplayValue := '+pas(dictionary(v['labels']))+';','        ExpectedPositions := '+str(len(v['labels']))+';','       End'+(';' if i==len(row['variants'])-1 else '')]
   lines+=['     End;']
  else:lines+=["     DisplayValue := ''; // "+row['status']]
 lines+=['    Else',"     DisplayValue := '';",'   End;','   // Recorded model configuration wins over an ICAO reference profile.','   If (HandlePositionCount > 0) And (ExpectedPositions > 0) And (HandlePositionCount <> ExpectedPositions) Then',"    DisplayValue := '';",'   Result := DisplayValue;','  End;','',' Function RecordedFlapPositionCount(Labels : TStrings; Const Values : TArray<Double>) : Integer;','  Var I : Integer; V : Double;','  Begin','   Result := 0;','   If Labels = Nil Then Exit;',"   I := Labels.IndexOf('flaps_num_handle_positions');",'   If (I < 0) Or (I >= Length(Values)) Then Exit;','   V := Values[I];','   If IsNan(V) Or IsInfinite(V) Then Exit;','   If (V >= 1) And (V <= 256) Then','    If V = Trunc(V) Then Result := Trunc(V);','  End;','','End.','']
 return '\n'.join(lines)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();data=json.loads((ROOT/'support/display-values/flaps.json').read_text(encoding='utf-8'));dest=ROOT/'src/Visualization/FlapsHandleU.pas';text=generate(data)
 if a.check:assert dest.read_text(encoding='utf-8-sig')==text,'Regenerate FlapsHandleU'
 else:dest.write_text(text,encoding='utf-8-sig',newline='\r\n')
 print('PASS:',len(data['aircraft']),'explicit ICAO cases; empty unknown default; model position count validation.')
